from collections import defaultdict

def calculate_transition_frequencies(document):
    frequencies = defaultdict(lambda: defaultdict(int))
    words = document.split()

    for word in words:
        for i in range(len(word) - 1):
            current_char = word[i]
            next_char = word[i + 1]
            frequencies[current_char][next_char] += 1

    return frequencies
```

### Step 2: Define Costs Based on Frequencies

Convert the frequency dictionary into costs. One way to represent cost might be to use the inverse of the frequency:

```python
def calculate_transition_costs(frequencies):
    costs = {}
    for current_char, next_chars in frequencies.items():
        total = sum(next_chars.values())  # Total transitions from current_char
        for next_char, count in next_chars.items():
            costs[(current_char, next_char)] = 1 / (count / total)  # Inverse frequency cost
    return costs
```

